"use client"

import { useEffect, useState } from "react"

import { cn } from "@/lib/utils"

import styles from "./loading-state.module.css"
import { ThinkingShimmer } from "./thinking-shimmer"

export type LoadingStateVariant = "drive" | "dots" | "orbit"

export interface LoadingStateProps {
  /** The current work message announced to assistive technology. */
  label?: string
  /** Visual treatment for the loading indicator. */
  variant?: LoadingStateVariant
  /** Show the elapsed duration beside the label. */
  showElapsed?: boolean
  className?: string
}

const chevronDelays = Array.from({ length: 9 }, (_, index) => {
  const row = Math.floor(index / 3)
  const column = index % 3
  return (column + Math.abs(row - 1)) * 90
})

const orbitOrder = [0, 1, 2, 5, 8, 7, 6, 3]
const orbitDelays = Array.from({ length: 9 }, (_, index) => {
  const position = orbitOrder.indexOf(index)
  return position === -1 ? null : position * 110
})

const patternByVariant: Record<
  LoadingStateVariant,
  { delays: Array<number | null>; duration: number; circular: boolean }
> = {
  drive: { delays: chevronDelays, duration: 650, circular: false },
  dots: { delays: chevronDelays, duration: 650, circular: true },
  orbit: { delays: orbitDelays, duration: 950, circular: false },
}

function useElapsed() {
  const [tenths, setTenths] = useState(0)

  useEffect(() => {
    const interval = window.setInterval(
      () => setTenths((value) => value + 1),
      100
    )
    return () => window.clearInterval(interval)
  }, [])

  const seconds = tenths / 10
  return seconds < 60
    ? `${seconds.toFixed(1)}s`
    : `${Math.floor(seconds / 60)}m ${(seconds % 60).toFixed(1)}s`
}

function LoadingState({
  label = "Working",
  variant = "drive",
  showElapsed = true,
  className,
}: LoadingStateProps) {
  const elapsed = useElapsed()
  const { delays, duration, circular } = patternByVariant[variant]

  return (
    <div
      data-slot="loading-state"
      data-variant={variant}
      className={cn(styles.root, className)}
      role="status"
    >
      <span aria-hidden className={styles.grid}>
        {delays.map((delay, index) => (
          <span
            // The grid position is stable for the lifetime of the indicator.
            key={index}
            className={cn(styles.pixel, circular && styles.circular)}
            style={
              delay === null
                ? undefined
                : {
                    animationDelay: `${delay}ms`,
                    animationDuration: `${duration}ms`,
                  }
            }
          />
        ))}
      </span>
      <ThinkingShimmer className={styles.label}>{label}</ThinkingShimmer>
      {showElapsed ? (
        <span aria-hidden className={styles.elapsed}>
          {elapsed}
        </span>
      ) : null}
    </div>
  )
}

export { LoadingState }
export default LoadingState

.root {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 0.625rem;
  color: var(--foreground);
}

.grid {
  display: grid;
  grid-template-columns: repeat(3, 4px);
  gap: 1.5px;
}

.pixel {
  width: 4px;
  height: 4px;
  border-radius: 1px;
  background: currentColor;
  opacity: 0.15;
  animation-name: pixel-on;
  animation-timing-function: ease-in-out;
  animation-iteration-count: infinite;
}

.circular {
  border-radius: 999px;
}

.pixel:nth-child(5) {
  animation: none;
  opacity: 0.07;
}

.label {
  font-size: 13px;
  font-weight: 500;
}

.elapsed {
  color: var(--muted-foreground);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

@keyframes pixel-on {
  0%,
  100% {
    opacity: 0.15;
    transform: scale(1);
  }
  45% {
    opacity: 1;
    transform: scale(1.28);
  }
}

@media (prefers-reduced-motion: reduce) {
  .pixel,
  .label {
    animation: none;
  }
}

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"

import { TextShimmer } from "./text-shimmer"

export interface ThinkingShimmerProps {
  /** Loading message shown to the user. */
  children?: ReactNode
  /** Seconds taken for one shimmer pass. */
  duration?: number
  className?: string
}

export function ThinkingShimmer({
  children = "Thinking…",
  duration = 2,
  className,
}: ThinkingShimmerProps) {
  return (
    <TextShimmer
      as="span"
      duration={duration}
      className={cn("font-medium", className)}
    >
      {children}
    </TextShimmer>
  )
}

import { createElement, type ElementType, type ReactNode } from "react"

import { cn } from "@/lib/utils"

import {
  TEXT_SHIMMER_CLASS_NAME,
  TEXT_SHIMMER_KEYFRAMES,
  textShimmerStyle,
} from "./text-shimmer-styles"

export interface TextShimmerProps {
  children: ReactNode
  as?: ElementType
  duration?: number
  className?: string
}

export function TextShimmer({
  children,
  as: Comp = "span",
  duration = 2,
  className,
}: TextShimmerProps) {
  return (
    <>
      <style>{TEXT_SHIMMER_KEYFRAMES}</style>
      {createElement(
        Comp,
        {
          style: textShimmerStyle(duration),
          className: cn("inline-block", TEXT_SHIMMER_CLASS_NAME, className),
        },
        children
      )}
    </>
  )
}

import type { CSSProperties } from "react"

/** Angled text mask: one sweep, then a pause. */
export const TEXT_SHIMMER_KEYFRAMES = `
@property --sono-mask-x {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 100%;
}
@keyframes sono-text-shimmer {
  0% { --sono-mask-x: 100%; }
  50%, 100% { --sono-mask-x: -100%; }
}
@media (prefers-reduced-motion: reduce) {
  .sono-text-shimmer {
    animation: none !important;
    -webkit-mask-image: none !important;
    mask-image: none !important;
  }
}`

export const TEXT_SHIMMER_CLASS_NAME = "sono-text-shimmer text-foreground"

const mask =
  "linear-gradient(-75deg, white calc(var(--sono-mask-x) + 20%), transparent calc(var(--sono-mask-x) + 30%), white calc(var(--sono-mask-x) + 100%))"

export function textShimmerStyle(duration: number): CSSProperties {
  return {
    WebkitMaskImage: mask,
    maskImage: mask,
    animation: `sono-text-shimmer ${duration}s linear infinite`,
  }
}
